// Colleges and departments a deal can be tagged with (a 系學會 deal only for 資工系) and a student
// may declare on their school card. NTU only so far. The data is generated by
// scripts/build_ntu_units.mjs from NTU's academics pages and course system (fetched 2026-09-26);
// codes are NTU's own: a college slug (`eecs`) or a four-character course-system code (`9020`).
import ntu from "../data/schools/ntu-units.json";

export type Dept = { code: string; zh: string; en: string; deg?: string };
export type College = { code: string; zh: string; en: string; depts: Dept[] };
/** What GET /api/schools/:code/units returns. */
export type SchoolUnits = { school: string; college: College[] };

export type UnitInfo =
  | { kind: "college"; code: string; zh: string; en: string }
  | { kind: "dept"; code: string; zh: string; en: string; deg?: string; college: string };

export const NTU: SchoolUnits = { school: ntu.school, college: ntu.college as College[] };

/** NTU's colleges, each with its departments (17 colleges, 158 departments). */
export const COLLEGES: College[] = NTU.college;
/** NTU's departments as one flat list, each naming its college. */
export const DEPARTMENTS: (Dept & { college: string })[] = COLLEGES.flatMap((c) =>
  c.depts.map((d) => ({ ...d, college: c.code }))
);

const SCHOOLS: Record<string, SchoolUnits> = { NTU };

// code -> unit, per school. College slugs and department codes never collide (the generator checks).
const INDEX = new Map<string, Map<string, UnitInfo>>();
for (const [school, data] of Object.entries(SCHOOLS)) {
  const byCode = new Map<string, UnitInfo>();
  for (const c of data.college) {
    byCode.set(c.code, { kind: "college", code: c.code, zh: c.zh, en: c.en });
    for (const d of c.depts) byCode.set(d.code, { kind: "dept", ...d, college: c.code });
  }
  INDEX.set(school, byCode);
}

/** A school's colleges and departments, or null if we have none for it. Codes are upper-cased. */
export function schoolUnits(school: string): SchoolUnits | null {
  return SCHOOLS[school.toUpperCase()] ?? null;
}

/** A college or department by code, or null if the school or code is unknown. */
export function unitInfo(school: string, code: string): UnitInfo | null {
  return INDEX.get(school.toUpperCase())?.get(code) ?? null;
}

/** True for a known college code or department code of that school. */
export function isUnit(school: string, code: string): boolean {
  return unitInfo(school, code) !== null;
}

/** The college code an NTU department belongs to, or null if the code is not an NTU department. */
export function collegeOf(deptCode: string): string | null {
  const u = unitInfo("NTU", deptCode);
  return u?.kind === "dept" ? u.college : null;
}
